// Compile new module independently until lead registers it in lib.rs.
pub use floatboard_core::{Result, store};
#[path = "../src/database_repair.rs"]
mod database_repair;
use std::{fs, path::PathBuf};
use serde_json::{json,Value};
use floatboard_core::store::Store;
struct Fixture(PathBuf);
impl Fixture {fn new()->Self{let p=std::env::temp_dir().join(format!("floatboard-repair-test-{}",uuid::Uuid::new_v4()));fs::create_dir(&p).unwrap();fs::create_dir(p.join("data")).unwrap();Self(p)}fn root(&self)->PathBuf{self.0.join("data")}}
impl Drop for Fixture {fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn task(id:&str,status:&str)->Value{json!({"id":id,"revision":2,"title":"fixture","status":status,"plan":[{"id":"s","title":"done","status":"completed","timing":{"seconds":10}}],"blockers":[],"evidence":[{"label":"fixture"}],"history":[{"secret":"not retained"}],"timing":{"seconds":10},"completion_archive_id":"obsolete"})}
fn fixture_db(f:&Fixture){let s=Store::open(&f.root(),false).unwrap();for(id,status)in[("h:s1","completed"),("h:s2","running")]{s.db.execute("insert into tasks values(?1,?2)",rusqlite::params![id,task(id,status).to_string()]).unwrap();}s.db.execute_batch("pragma wal_checkpoint(TRUNCATE)").unwrap();}
fn hashes(root:&std::path::Path)->Vec<(String,String)>{["events.sqlite3","events.sqlite3-wal","events.sqlite3-shm"].iter().filter_map(|n|fs::read(root.join(n)).ok().map(|b|(n.to_string(),store::hash(&b)))).collect()}
#[test]fn healthy_copy_preserves_sources_and_rebuilds_actual_store(){let f=Fixture::new();fixture_db(&f);let before=hashes(&f.root());let r=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true})).unwrap();assert_eq!(before,hashes(&f.root()));assert_eq!(r["status"],"partial_recovery");assert_eq!(r["recovery"]["recovered_tasks"],2);assert_eq!(r["recovery"]["reconstructed_current_completions"],1);assert_eq!(r["recovery"]["omitted_tasks"],0);assert_eq!(r["coordinated_snapshot"],false);let dest=f.0.join(r["paths"]["recovered_database"].as_str().unwrap()).parent().unwrap().to_path_buf();let mut s=Store::open(&dest,true).unwrap();let tasks=s.tasks().unwrap();assert_eq!(tasks.len(),2);for t in tasks{assert!(t["timing"].is_null());assert_eq!(t["recovery_provenance"]["history_recovered"],false);}assert_eq!(s.db.query_row("select count(*) from events",[],|r|r.get::<_,i64>(0)).unwrap(),0);let snapshot=database_repair::call(&f.root(),"snapshot",&json!({})).unwrap();assert_eq!(snapshot,r);}
#[test]fn invalid_database_is_preserved_without_claiming_recovery(){let f=Fixture::new();fs::write(f.root().join("events.sqlite3"),b"definitely not sqlite").unwrap();let before=hashes(&f.root());let r=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true})).unwrap();assert_eq!(before,hashes(&f.root()));assert!(["unreadable_copy","no_readable_tasks"].contains(&r["status"].as_str().unwrap()));assert!(r["paths"]["recovered_database"].is_null());assert!(!r.to_string().contains(f.0.to_str().unwrap()));}
#[test]fn rejects_apply_paths_and_missing_confirmation(){let f=Fixture::new();fixture_db(&f);let before=hashes(&f.root());for(action,p)in[("apply",json!({"confirmed":true})),("recover_copy",json!({})),("recover_copy",json!({"confirmed":true,"path":"C:/anywhere"})),("inspect",Value::Null)]{assert!(database_repair::call(&f.root(),action,&p).is_err());}assert_eq!(before,hashes(&f.root()));assert!(!f.0.join("control").exists());}
#[test]fn corrupt_task_row_does_not_hide_other_rows(){let f=Fixture::new();fixture_db(&f);{let s=Store::open(&f.root(),true).unwrap();drop(s);}let db=rusqlite::Connection::open(f.root().join("events.sqlite3")).unwrap();db.execute("insert into tasks values('bad','{')",[]).unwrap();db.execute_batch("pragma wal_checkpoint(TRUNCATE)").unwrap();drop(db);let before=hashes(&f.root());let r=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true})).unwrap();assert_eq!(before,hashes(&f.root()));assert_eq!(r["recovery"]["recovered_tasks"],2);assert_eq!(r["recovery"]["rejected_rows"],1);assert_eq!(r["recovery"]["omitted_tasks"],1);}
#[test]fn writer_open_is_always_reported_as_uncoordinated(){let f=Fixture::new();fixture_db(&f);let writer=rusqlite::Connection::open(f.root().join("events.sqlite3")).unwrap();writer.execute_batch("pragma journal_mode=WAL; begin immediate;").unwrap();writer.execute("insert into tasks values('pending',?1)",[task("pending","running").to_string()]).unwrap();let before=hashes(&f.root());let result=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true}));assert_eq!(before,hashes(&f.root()));match result {Ok(r)=>{assert_eq!(r["coordinated_snapshot"],false);assert_eq!(r["partial"],true);assert_eq!(r["apply_supported"],false);assert_eq!(r["recovery"]["recovered_tasks"],2);},Err(e)=>assert!(["源文件读取失败","源文件不可读","数据库副本读取失败","数据库复制失败"].contains(&e.as_str())),}writer.execute_batch("rollback").unwrap();}
#[test]fn missing_database_never_creates_source(){let f=Fixture::new();assert!(database_repair::call(&f.root(),"inspect",&json!({})).is_err());assert!(!f.root().join("events.sqlite3").exists());}
#[test]fn unique_evidence_and_inspection_does_not_create_recovered_database(){let f=Fixture::new();fixture_db(&f);let a=database_repair::call(&f.root(),"inspect",&json!({})).unwrap();let b=database_repair::call(&f.root(),"inspect",&json!({})).unwrap();assert_ne!(a["recovery_id"],b["recovery_id"]);assert_eq!(a["source_copy_integrity_ok"],true);assert!(a["paths"]["recovered_database"].is_null());}
#[test]fn refuses_symlink_or_junction_control(){let f=Fixture::new();fixture_db(&f);let target=f.0.join("other");fs::create_dir(&target).unwrap();#[cfg(windows)]{let status=std::process::Command::new("cmd").args(["/c","mklink","/J"]).arg(f.0.join("control")).arg(&target).status().unwrap();assert!(status.success());}#[cfg(not(windows))]std::os::unix::fs::symlink(&target,f.0.join("control")).unwrap();assert!(database_repair::call(&f.root(),"inspect",&json!({})).is_err());}
#[test]fn unsupported_tasks_view_cannot_enable_index_fallback(){let f=Fixture::new();let db=rusqlite::Connection::open(f.root().join("events.sqlite3")).unwrap();db.execute_batch("create table raw(id text primary key,payload);create view tasks as select id,payload from raw;insert into raw values('bad',NULL);").unwrap();drop(db);let before=hashes(&f.root());let r=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true})).unwrap();assert_eq!(before,hashes(&f.root()));assert_eq!(r["recovery"]["recovered_tasks"],0);assert_eq!(r["recovery"]["indexed_fallback"],false);assert_eq!(r["recovery"]["counts_are_best_effort"],true);}
#[test]
fn preserved_placeholders_do_not_inflate_application_task_count(){
 let f=Fixture::new();fixture_db(&f);
 {let s=Store::open(&f.root(),false).unwrap();for i in 0..5 {let id=format!("placeholder:{i}");let task=json!({"id":id,"revision":-1,"status":"unreported","plan":[],"blockers":[],"evidence":[],"history":[]});s.db.execute("insert into tasks values(?1,?2)",rusqlite::params![id,task.to_string()]).unwrap();}s.db.execute_batch("pragma wal_checkpoint(TRUNCATE)").unwrap();}
 let before=hashes(&f.root());let report=database_repair::call(&f.root(),"recover_copy",&json!({"confirmed":true})).unwrap();
 assert_eq!(before,hashes(&f.root()));assert_eq!(report["recovery"]["recovered_task_rows"],7);assert_eq!(report["recovery"]["recovered_tasks"],2);assert_eq!(report["recovery"]["omitted_tasks"],0);
 let dest=f.0.join(report["paths"]["recovered_database"].as_str().unwrap()).parent().unwrap().to_path_buf();let mut s=Store::open(&dest,true).unwrap();assert_eq!(s.tasks().unwrap().len(),2);assert_eq!(s.db.query_row("select count(*) from tasks",[],|r|r.get::<_,i64>(0)).unwrap(),7);
}
#[test]fn refuses_large_sparse_database(){let f=Fixture::new();let file=fs::File::create(f.root().join("events.sqlite3")).unwrap();file.set_len(256*1024*1024+1).unwrap();assert!(database_repair::call(&f.root(),"inspect",&json!({})).is_err());}
